"""Construction UI regression. HTTP = native ES modules and origin storage.
--offline = local ES module import map and explicit memory Storage, not PWA QA.
"""
import argparse, functools, http.server, importlib.util, json, os, threading
from pathlib import Path
from playwright.sync_api import sync_playwright
ROOT = Path(__file__).resolve().parents[1]

def main():
    parser = argparse.ArgumentParser(); parser.add_argument('--output', default='/tmp/forge-v135-browser'); parser.add_argument('--offline', action='store_true')
    args = parser.parse_args(); out = Path(args.output); out.mkdir(parents=True, exist_ok=True)
    spec = importlib.util.spec_from_file_location('host', ROOT/'scripts/forge-offline-harness-v130.py'); host = importlib.util.module_from_spec(spec); spec.loader.exec_module(host)
    html = host.build_offline_html(ROOT) if args.offline else None
    server = None; results = []; errors = []
    class Handler(http.server.SimpleHTTPRequestHandler):
        def log_message(self, *_): pass
    if not args.offline:
        server = http.server.ThreadingHTTPServer(('127.0.0.1', 0), functools.partial(Handler, directory=str(ROOT)))
        threading.Thread(target=server.serve_forever, daemon=True).start()
    def check(name, passed):
        results.append({'name': name, 'passed': bool(passed)})
        print(('PASS ' if passed else 'FAIL ')+name, flush=True)
        if not passed: raise AssertionError(name)
    try:
        with sync_playwright() as p:
            browser = p.chromium.launch(executable_path=os.environ.get('CHROMIUM_PATH','/usr/bin/chromium'), headless=True, args=['--no-sandbox'])
            page = browser.new_page(viewport={'width':1600,'height':1050}, accept_downloads=True)
            page.set_default_timeout(10000)
            print('BROWSER READY', flush=True)
            confirm = {'accept': True}; page.on('dialog', lambda d: d.accept() if confirm['accept'] else d.dismiss()); page.on('pageerror', lambda e: errors.append(str(e)))
            def load(records=None):
                if args.offline: host.prepare_offline_page(page, html, records)
                else: page.goto(f'http://127.0.0.1:{server.server_port}/scripts/fixtures/forge-v130.html')
                page.wait_for_function('!!window.forgeEditor?.constructionV135'); page.wait_for_timeout(50)
            def field(n): return page.locator(f'[data-build-field="{n}"]')
            def click(n): page.click(f'[data-build-action="{n}"]')
            def snap(): return page.evaluate('JSON.stringify(forgeEditor.model.data)')
            def status(): return page.locator('[data-build-status]').inner_text()
            load(); page.click('[data-tab="construction"]')
            check('construction tab mounts in existing workbench', page.locator('#forge-panel-construction-v135').is_visible())
            check('eight programs and four silhouettes exposed', field('profile').locator('option').count()==8 and field('shape').locator('option').count()==4)
            check('construct requires an explicit preview', page.locator('[data-build-action="apply"]').is_disabled())
            page.evaluate("localStorage.setItem('atf-v47-profile-1','campaign-proof')")
            before = snap(); writes = page.evaluate('getChangeCount()'); stored = page.evaluate('localStorage.getItem(forgeStore.key)')
            field('profile').select_option('laboratory'); field('shape').select_option('leftWing'); field('height').fill('24'); field('levels').select_option('3'); field('name').fill('Laboratoire des ailes hautes')
            check('changing recipe never mutates the current document', snap()==before)
            click('preview')
            check('preview supplies a valid three-level room', page.evaluate('forgeEditor.constructionV135.getPlan().blueprint.decks.length===3'))
            check('preview does not add history or rooms', snap()==before and page.evaluate('forgeEditor.history.length')==0)
            check('preview does not invoke persistence', page.evaluate('getChangeCount()')==writes and page.evaluate('localStorage.getItem(forgeStore.key)')==stored)
            check('preview enables the build action', page.locator('[data-build-action="apply"]').is_enabled())
            check('preview report identifies symbolic grid scope', 'Pas de validation physique' in page.locator('[data-build-report]').inner_text())
            preview = page.evaluate('JSON.stringify(forgeEditor.constructionV135.getPlan().blueprint.room)'); click('preview')
            check('repeated preview is deterministic', page.evaluate('JSON.stringify(forgeEditor.constructionV135.getPlan().blueprint.room)')==preview)
            page.screenshot(path=str(out/'construction-preview-1600.png'), full_page=True)
            click('apply'); after = snap()
            check('build adds a room without replacing the current room', page.evaluate('forgeEditor.model.data.rooms.length===2 && forgeEditor.model.data.rooms[0].cells.length===0'))
            check('build becomes exactly one history entry and one change callback', page.evaluate('forgeEditor.history.length')==1 and page.evaluate('getChangeCount()')==writes+1)
            check('built room remains native editable schema 3', page.evaluate("forgeEditor.room.name==='Laboratoire des ailes hautes' && forgeEditor.model.data.schema===3"))
            page.click('#editor-undo'); check('undo restores the entire pre-build document', snap()==before)
            page.click('#editor-redo'); check('redo restores byte-identical generated room', snap()==after)
            check('successful build clears the preview', page.locator('[data-build-action="apply"]').is_disabled())
            source = page.evaluate("forgeEditor.room.id+':'+forgeEditor.room.cells.find(c=>c.type==='door').id")
            field('source').select_option(source); field('profile').select_option('maintenance'); field('name').fill('Maintenance raccordée'); field('entry').select_option('right'); click('preview')
            before_link = snap(); click('apply')
            check('new room connects from the chosen free door', page.evaluate('forgeEditor.model.data.links.length===1'))
            link = page.evaluate('forgeEditor.model.data.links[0]')
            check('generated entry respects chosen side', page.evaluate('forgeEditor.room.cells.find(c=>c.id===forgeEditor.model.data.links[0].to.cellId).x===30'))
            check('connection did not change any previous room blocks', json.loads(snap())['rooms'][:2]==json.loads(before_link)['rooms'])
            page.click('#editor-undo'); check('undo removes room and connection together', snap()==before_link)
            page.click('#editor-redo'); field('destination').select_option('replace')
            field('profile').select_option('quarters'); field('shape').select_option('stepped'); click('preview'); before_replace = snap()
            confirm['accept'] = False; click('apply'); confirm['accept'] = True
            check('declining reconstruction leaves document unchanged', snap()==before_replace)
            click('apply')
            check('compatible linked socket keeps its stable ID on replacement', page.evaluate('forgeEditor.model.data.links[0]')==link)
            check('replace creates no extra room', page.evaluate('forgeEditor.model.data.rooms.length')==3)
            field('height').fill('30'); before = snap(); click('preview')
            check('linked socket displacement is refused visibly', 'sas relié' in status() and snap()==before)
            check('invalid preview cannot be applied', page.locator('[data-build-action="apply"]').is_disabled())
            field('height').fill('24'); click('preview'); field('seed').fill('777')
            check('changing seed invalidates the prior preview', page.locator('[data-build-action="apply"]').is_disabled())
            click('preview'); click('variation'); check('next-variant increments a reproducible seed', field('seed').input_value()=='778')
            before = snap(); page.locator('[data-build-action="preview"]').focus(); page.keyboard.press('Escape')
            check('Escape cancels construction preview without closing Forge', page.locator('#forge-panel-construction-v135').is_visible() and page.locator('[data-build-action="apply"]').is_disabled() and snap()==before)
            click('preview'); page.evaluate("forgeEditor.edit('lock fixture',()=>{forgeEditor.room.cells[0].locked=true})"); before=snap(); click('preview')
            check('reconstruction cannot discard a locked cell', 'verrouillé' in status() and snap()==before)
            page.click('#editor-undo'); field('destination').select_option('new'); click('preview')
            page.click('[data-forge-action="visibility"][data-layer="background"]'); check('hiding a participating layer cancels preview', page.locator('[data-build-action="apply"]').is_disabled())
            before=snap(); click('preview'); check('building onto a hidden layer is refused', 'masqué' in status() and snap()==before)
            page.click('[data-forge-action="visibility"][data-layer="background"]'); click('preview')
            # Download then import of a recipe affects the form only.
            page.locator('#forge-panel-construction-v135 details').evaluate('(n)=>n.open=true')
            with page.expect_download() as d: click('recipe-export')
            path=out/'exported-recipe.json'; d.value.save_as(path); recipe=json.loads(path.read_text())
            check('download contains versioned recipe, not workspace data', recipe['format']=='frontier-forge-recipe' and 'rooms' not in recipe)
            field('seed').fill('555'); before=snap(); page.set_input_files('[data-build-import]',str(path)); page.wait_for_function("document.querySelector('[data-build-status]').textContent.startsWith('Recette chargée')")
            check('import restores parameters without changing level', field('seed').input_value()=='778' and snap()==before)
            check('recipe import requires another preview', page.locator('[data-build-action="apply"]').is_disabled())
            page.set_input_files('[data-build-import]',{'name':'bad.json','mimeType':'application/json','buffer':b'{bad'})
            page.wait_for_function("document.querySelector('[data-build-status]').textContent.includes('illisible')")
            check('malformed recipe keeps form and level', field('seed').input_value()=='778' and snap()==before)
            check('recipe input resets after failed import', page.locator('[data-build-import]').input_value()=='')
            page.set_input_files('[data-build-import]',{'name':'big.json','mimeType':'application/json','buffer':b' '*16385})
            page.wait_for_function("document.querySelector('[data-build-status]').textContent.includes('volumineuse')")
            check('oversized recipe is rejected before reading', snap()==before)
            page.evaluate("window.originalFileText=File.prototype.text;File.prototype.text=function(){return new Promise(resolve=>{window.finishRecipe=()=>resolve(window.recipeText)})};void 0")
            page.evaluate('(raw)=>window.recipeText=raw',path.read_text()); page.set_input_files('[data-build-import]',str(path)); field('seed').fill('902'); page.evaluate('finishRecipe(); File.prototype.text=originalFileText;void 0')
            page.wait_for_function("document.querySelector('[data-build-status]').textContent.includes('pendant la lecture')")
            check('async stale recipe read cannot replace newer form edits', field('seed').input_value()=='902')
            # Untrusted names remain text in preview, inspector and room graph.
            field('name').fill('<img src=x onerror="window.injected=true">'); click('preview')
            check('preview never interprets a room name as HTML', not page.evaluate('!!window.injected') and page.locator('#forge-panel-construction-v135 img').count()==0)
            before=snap(); page.click('[data-tab="projects"]'); page.fill('[data-work-field="project-name"]','Nouveau brouillon'); page.click('[data-work-action="project-create"]'); page.click('[data-tab="construction"]')
            check('project switch cancels another documents preview', page.locator('[data-build-action="apply"]').is_disabled())
            field('profile').select_option('hangar'); field('vehicle').check(); page.select_option('#editor-mode','ship')
            check('ship mode prevents unsupported vehicle option', field('vehicle').is_disabled() and not field('vehicle').is_checked())
            field('height').fill('24'); field('levels').select_option('2'); field('name').fill('Passerelles de relève'); click('preview'); click('apply')
            check('ship blueprint is built in ship document without mode reset', page.evaluate("forgeEditor.model.data.kind==='ship' && forgeEditor.room.name==='Passerelles de relève'"))
            check('campaign storage key remains unchanged', page.evaluate("localStorage.getItem('atf-v47-profile-1')")=='campaign-proof')
            saved=snap(); records=page.evaluate('localStorage.dump()') if args.offline else None; load(records); page.wait_for_function("forgeEditor.room.name==='Passerelles de relève'")
            check('built rooms survive actual store reload without flattening', snap()==saved)
            check('reloaded project has no empty-document undo entry', page.evaluate('forgeEditor.history.length')==0)
            page.click('[data-tab="construction"]'); field('height').fill('24'); field('levels').select_option('2'); field('shape').select_option('twinWings'); field('name').fill('Ailes de maintenance'); click('preview')
            for width,height in [(1600,1050),(1024,768),(390,844)]:
                page.set_viewport_size({'width':width,'height':height}); page.screenshot(path=str(out/f'construction-{width}.png'),full_page=True)
                check(f'construction has no horizontal overflow at {width}px',page.evaluate('document.documentElement.scrollWidth<=innerWidth+1'))
                check(f'preview canvas usable at {width}px',page.locator('[data-build-canvas]').bounding_box()['width']>200)
            check('no uncaught page errors during full workflow',not errors)
            browser.close()
    finally:
        if server: server.shutdown(); server.server_close()
        (out/'results.json').write_text(json.dumps({'mode':'offline-memory' if args.offline else 'http-native-storage','checks':len(results),'passed':sum(r['passed'] for r in results),'results':results,'pageErrors':errors},ensure_ascii=False,indent=2))
    print(json.dumps({'checks':len(results),'passed':sum(r['passed'] for r in results)},ensure_ascii=False))
if __name__=='__main__': main()
